mapper.select:
select
  id, study_id, exam_no, test_no, abnormal_indicator_high, abnormal_indicator_low, create_time, update_time, triiodothyronine, thyroxine, thyroid_stimulating_hormone, free_triiodothyronine, free_thyroxine, antithyroglobulin_antibody, antithyroid_peroxidase_antibody, thyrotropin_receptor_antibody
from td_thyroid_function_items


        and id = #{id}


        and study_id = #{studyId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


        and abnormal_indicator_high = #{abnormalIndicatorHigh}


        and abnormal_indicator_low = #{abnormalIndicatorLow}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and triiodothyronine = #{triiodothyronine}


        and thyroxine = #{thyroxine}


        and thyroid_stimulating_hormone = #{thyroidStimulatingHormone}


        and free_triiodothyronine = #{freeTriiodothyronine}


        and free_thyroxine = #{freeThyroxine}


        and antithyroglobulin_antibody = #{antithyroglobulinAntibody}


        and antithyroid_peroxidase_antibody = #{antithyroidPeroxidaseAntibody}


        and thyrotropin_receptor_antibody = #{thyrotropinReceptorAntibody}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from td_thyroid_function_items


        and id = #{id}


        and study_id = #{studyId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


        and abnormal_indicator_high = #{abnormalIndicatorHigh}


        and abnormal_indicator_low = #{abnormalIndicatorLow}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and triiodothyronine = #{triiodothyronine}


        and thyroxine = #{thyroxine}


        and thyroid_stimulating_hormone = #{thyroidStimulatingHormone}


        and free_triiodothyronine = #{freeTriiodothyronine}


        and free_thyroxine = #{freeThyroxine}


        and antithyroglobulin_antibody = #{antithyroglobulinAntibody}


        and antithyroid_peroxidase_antibody = #{antithyroidPeroxidaseAntibody}


        and thyrotropin_receptor_antibody = #{thyrotropinReceptorAntibody}
